functions.formula_display:
=LAMBDA(X_s, [Allow_Intercept], [Filter],
  1 / VIF(X_s, Allow_Intercept, Filter)
)

=LAMBDA(Y, [Filter],
  SEQUENCE(ROWS(FILTER(Y, IF(ISOMITTED(Filter), TRUE, Filter))))
)

=LAMBDA(Y, [Filter],
  SORT(FILTER(Y, IF(ISOMITTED(Filter), TRUE, Filter)))
)

=LAMBDA(X,
  MINVERSE(MMULT(TRANSPOSE(X), X))
)

=LAMBDA(array,
  SEQUENCE(ROWS(array))
)

=LAMBDA(table, col_nums,
  CHOOSECOLS(table, col_nums)
)

=LAMBDA(X_s, [Y],
  LET(
    combined, IF(ISOMITTED(Y), X_s, HSTACK(X_s, Y)),
    MMULT((ISNUMBER(combined)) * 1, SEQUENCE(COLUMNS(combined), 1, 1, 0)) = COLUMNS(combined)
  )
)
